 // Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
 // n is any size from 1 to 2048.
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
+#if defined(__ARM_NEON)
+    for (int i = 0; i < n; ++i) {
+        float* Ci = C + i * n;
+        // zero C row
+        for (int j = 0; j < n; ++j) Ci[j] = 0.0f;
+        const float* Ai = A + i * n;
+        for (int k = 0; k < n; ++k) {
+            float aik = Ai[k];
+            const float* Bk = B + k * n;
+            int j = 0;
+            for (; j + 3 < n; j += 4) {
+                float32x4_t bvec = vld1q_f32(Bk + j);
+                float32x4_t cvec = vld1q_f32(Ci + j);
+                cvec = vfmaq_f32(cvec, bvec, vdupq_n_f32(aik));
+                vst1q_f32(Ci + j, cvec);
+            }
+            for (; j < n; ++j) Ci[j] += aik * Bk[j];
+        }
+    }
+#else
     for (int i = 0; i < n; ++i)
         for (int j = 0; j < n; ++j) {
             float s = 0.0f;
             for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
             C[i * n + j] = s;
         }
+#endif
 }
 // OMEGA-BLOCK-END
